/* parcours « L'essentiel en 15 minutes » */
const ESSENTIEL=['centrale','site','chaine','retardes','stabilite','agir','primaire','gv','barrieres','residuelle','tmivoir','salle'];

/* Thèmes de la visite, dans l'ordre : chaque chapitre est désigné par son identifiant (id des chapitres de base, clé de NEWCH sinon).
   Le 4e élément range le thème dans une des trois parties (PARTIES) : bandeau des thèmes et sommaire. */
const PARTIES=[['comprendre','Comprendre'],['piloter','Piloter'],['surete','Sûreté']];
const THEMES=[
 ['centrale','La centrale',['centrale','site'],'comprendre'],
 ['physique','Le cœur et la réaction',['fission','chaine','pcm','retardes','doublement','combustible'],'comprendre'],
 ['contre','Contre-réactions et xénon',['moderateur','stabilite','xeanim','xenon'],'comprendre'],
 ['circuits','Circuits',['primaire','pressu','chaussette','gv','turbine','condenseur'],'comprendre'],
 ['electricite','Électricité',['elsrc','elsecu','elilot','eldg','elcn','elbat'],'comprendre'],
 ['pilotage','Grappes et pilotage',['agir','groupes','modeg','rband','dianim','params'],'piloter'],
 ['manoeuvres','Démarrer et arrêter',['etats','comptage','diverg','couplage','montee','repli'],'piloter'],
 ['production','En production',['leviers','freq','suivi'],'piloter'],
 ['conduite','Conduite',['regles','method','salle'],'piloter'],
 ['surete','Protections et arrêts',['barrieres','residuelle','imprevu'],'surete'],
 ['histo','Accidents historiques',['tmi','tmivoir','tmidiff','tmiapres','fuku','fukufr'],'surete']
];
/* range les chapitres selon THEMES ; tests/interface.test.mjs vérifie que chaque identifiant existe */
(()=>{ const byId=Object.fromEntries(TOUR.map(c=>[c.id,c])); for(const [k,c] of Object.entries(NEWCH)) c.id=k; const out=[];
  for(const [id,name,list] of THEMES) for(const key of list){ const c=byId[key]||NEWCH[key]; if(!c) continue; c.th=id; c.k=name; out.push(c); }
  for(const c of TOUR) if(!out.includes(c)){ c.th='centrale'; out.push(c); }
  TOUR.length=0; out.forEach(c=>TOUR.push(c)); })();
